{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울형 키즈카페 경계에서 25m 떨어진 누구나 다닐 수 있는 보행로를 서울시가 금연구역으로 지정할 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울형 키즈카페 시설의 경계선으로부터 30미터 이내의 구역은 일반 공중의 통행·이용 등에 제공된 구역이면 시장이 금연구역으로 지정할 수 있다. 질문의 보행로는 키즈카페 경계에서 25m 떨어져 있고 누구나 다닐 수 있는 보행로이므로 30미터 이내이면서 일반 공중의 통행·이용에 제공된 구역에 해당한다. 따라서 서울시는 해당 보행로를 금연구역으로 지정할 수 있다.",
          "b_ids": "금연:제5조제1항제5호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
